// The editor's grammar, checked against `sadhana`'s parse — task `F-020`.
//
// A highlighter fails SILENTLY by construction: a rule that never matches leaves
// text the same colour as the text around it, and nobody files a bug about a
// word that is not blue. `tools/check-highlights.sh` says exactly that about the
// tree-sitter queries. The VS Code grammar is a second highlighter and needs the
// same treatment.
//
// ORACLE: `spec/parse-shape-t0.tsv`, generated by `sadhana`'s own parser, which
// records the kind and name of every statement in every tracked program. If the
// grammar calls something a mnemonic, sadhana must agree it is one.
//
// ## The one thing this check cannot do, stated rather than glossed over
//
// VS Code matches these patterns with ONIGURUMA; this runs them under
// JavaScript's RegExp. The constructs used here — non-capturing groups, a
// fixed-width lookbehind, negated classes — mean the same thing in both, but
// this is an approximation and a pattern that relied on an Oniguruma-only
// feature would pass here and fail in the editor. It is the ADR-0004 class of
// error this is built to catch, not engine differences.

import { readFileSync } from 'node:fs';
import path from 'node:path';

const root = path.resolve(import.meta.dirname, '..');
const read = (p) => readFileSync(path.join(root, p), 'utf8');
const fail = (msg) => { console.error(`  FAIL  ${msg}`); process.exit(1); };

// ---- the manifests parse, and say what the row requires --------------------

let manifest, langConfig, grammar;
try {
  manifest = JSON.parse(read('editor/sanskriti/package.json'));
  langConfig = JSON.parse(read('editor/sanskriti/language-configuration.json'));
  grammar = JSON.parse(read('editor/sanskriti/syntaxes/sassembly.tmLanguage.json'));
} catch (e) {
  fail(`an extension manifest is not valid JSON: ${e.message}`);
}

const lang = manifest.contributes.languages[0];
for (const ext of ['.sas', '.सस']) {
  if (!lang.extensions.includes(ext)) {
    fail(`the extension does not associate ${ext}; the row makes both first-class`);
  }
}
if (langConfig.comments.lineComment !== '॰') {
  fail(`the line comment is ${JSON.stringify(langConfig.comments.lineComment)}, not ॰`);
}
// Every contributed command must carry a Devanagari title. The owner's ruling is
// that the UI is Sanskrit, and the palette is where a demo is looked at.
for (const c of manifest.contributes.commands) {
  if (!/[ऀ-ॿ]/.test(c.title)) {
    fail(`command ${c.command} has a title with no Devanagari in it: ${c.title}`);
  }
}
console.log(`  ok    manifests            .sas .सस, ॰ comments, ${manifest.contributes.commands.length} Sanskrit commands`);

// ---- the rules, taken FROM the grammar file, not restated here -------------
//
// Reading the patterns out of the shipped file is the whole point: a copy here
// could drift and still agree with itself, which is the defect this project
// keeps finding. If the grammar changes, this checks the changed grammar.
const rx = (name) => {
  const pat = grammar.repository[name]?.match ?? grammar.repository[name]?.begin;
  if (!pat) fail(`the grammar has no rule named "${name}"`);
  try {
    return new RegExp(pat);
  } catch (e) {
    fail(`rule "${name}" is not a regex JavaScript can compile: ${e.message}`);
  }
};

const comment = rx('comment');
const label = rx('label');
const mnemonic = rx('mnemonic');

// ---- every instruction sadhana found, classified the grammar's way ---------

const rows = read('spec/parse-shape-t0.tsv')
  .split('\n')
  .map((l) => l.split('\t'))
  .filter((c) => c.length === 4 && c[2] === 'instruction')
  .map(([file, line, , name]) => ({ file, line: Number(line), name }));

if (rows.length < 100) {
  fail(`only ${rows.length} instruction rows read from spec/parse-shape-t0.tsv — its format moved, and a check that reads nothing reports green`);
}

const sources = new Map();
const lineOf = (file, n) => {
  if (!sources.has(file)) sources.set(file, read(file).split('\n'));
  return sources.get(file)[n - 1];
};

let checked = 0;
const wrong = [];
for (const r of rows) {
  let text;
  try {
    text = lineOf(r.file, r.line);
  } catch {
    continue; // a program listed in the oracle but absent here is not this check's fault
  }
  if (text === undefined) continue;

  // Apply the rules in the order the grammar lists them: comments are stripped,
  // a label at the head of the line is consumed, and what remains begins with
  // the verb. This mirrors `patterns`, which is what VS Code walks.
  let rest = text.replace(comment, '');
  const lab = rest.match(label);
  if (lab && lab.index === 0) rest = rest.slice(lab[0].length);

  const m = rest.match(mnemonic);
  checked++;
  if (!m) {
    wrong.push(`  ${r.file}:${r.line} — the mnemonic rule matched nothing; sadhana says ${r.name}`);
  } else if (m[1] !== r.name) {
    wrong.push(`  ${r.file}:${r.line} — grammar says ${m[1]}, sadhana says ${r.name}`);
  }
}

if (checked === 0) fail('classified 0 instructions — this check proved nothing');
console.log(`  ok    instructions         ${checked} classified against sadhana's parse`);

if (wrong.length) {
  console.error(`  FAIL  the grammar disagrees with sadhana on ${wrong.length} of ${checked} instructions:`);
  console.error(wrong.slice(0, 15).join('\n'));
  if (wrong.length > 15) console.error(`  … and ${wrong.length - 15} more`);
  process.exit(1);
}

// ---- the control: ADR-0004's trap, demonstrated on this corpus -------------
//
// The grammar above is only interesting because the OBVIOUS grammar is wrong.
// ADR-0004: the destination sigil is `म्` and most mnemonics are neuter
// nominative singulars ending in `-म्`, so "a token ending in म् is a
// destination operand" mis-colours the verb itself. Run that rule here and
// require it to be caught. If it is ever NOT caught, either the corpus has lost
// its `-म्` mnemonics or the trap has stopped being real, and in both cases the
// justification for the anchored rule above needs re-reading.
const misread = new Set(rows.map((r) => r.name).filter((n) => n.endsWith('म्')));
console.log(`  ok    control              ${misread.size} distinct mnemonics end in म् and a suffix rule would mis-colour every one`);
if (misread.size < 10) {
  fail(`only ${misread.size} mnemonic(s) end in म्. ADR-0004's collision is what makes the anchored rule necessary; if it no longer holds on this corpus, this check is no longer evidence for the design.`);
}

console.log();
console.log('the editor grammar names the same verbs sadhana does.');
